import subprocess, time, os, shlex
def capture(args):
    import random, time as tt
    sess=f"s{int(tt.time()*5000)%100000}_{random.randint(0,9999)}"
    subprocess.run(["tmux","kill-session","-t",sess], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    shell=" ".join(shlex.quote(c) for c in args)
    subprocess.run(["tmux","new-session","-d","-s",sess, shell], check=True)
    tt.sleep(0.6)
    txt=subprocess.run(["tmux","capture-pane","-p","-t",sess], capture_output=True, text=True).stdout
    subprocess.run(["tmux","kill-session","-t",sess], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    return txt
def lesson(txt):
    ls=txt.splitlines()
    for i,l in enumerate(ls):
        if "Lesson" in l and i+3<len(ls):
            return ls[i+3].strip("│ ").strip()
    return ""
# trigrams
for top in [10,20]:
    uniq=set()
    for _ in range(60):
        uniq.add(lesson(capture(["./executable","--n","3","--top",str(top),"--combi","1","--rep","1"])))
    print(f"tri {top} {len(uniq)} {sorted(uniq)}")
