import subprocess, time, os, shlex, random, concurrent.futures

def cap_once(args):
    sess = f"sam_{int(time.time()*1000000)}_{random.randint(0,999999)}"
    subprocess.run(["tmux","kill-session","-t",sess], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    sh = " ".join(shlex.quote(c) for c in args)
    subprocess.run(["tmux","new-session","-d","-s",sess, "-x","80","-y","24", sh], check=True)
    time.sleep(0.55)
    txt = subprocess.run(["tmux","capture-pane","-p","-t",sess], capture_output=True, text=True).stdout
    subprocess.run(["tmux","kill-session","-t",sess], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    for i,l in enumerate(txt.splitlines()):
        if "Lesson" in l and i+3 < len(txt.splitlines()):
            inner = txt.splitlines()[i+3].strip("│ ").strip()
            return inner
    return ""

def sample(n_flag, top, trials=200, parallel=12):
    pool=set()
    def task(_):
        return cap_once(["./executable","--n",n_flag,"--top",str(top),"--combi","1","--rep","1"])
    with concurrent.futures.ThreadPoolExecutor(max_workers=parallel) as ex:
        futures=[ex.submit(task, i) for i in range(trials)]
        for f in concurrent.futures.as_completed(futures):
            try:
                lesson=f.result()
                if lesson:
                    pool.add(lesson.strip())
            except: pass
    return pool

# sample trigrams etc
for n_flag, name in [("3","tri"),("4","tetra"),("w","words")]:
    for top, trials in [(20,200),(50,250)]:
        start=time.time()
        pool=sample(n_flag, top, trials=trials, parallel=12)
        print(f"{name} top {top} pool {len(pool)} sorted {sorted(pool)[:80]}")
        print(f"full {sorted(pool)}")
        print(f"time {time.time()-start:.1f}\n")
