import subprocess, pty, os, time, fcntl, select, struct, termios, re

def cap_with_width(width, args):
    master, slave = pty.openpty()
    try:
        fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", 24, width, 0,0))
    except: pass
    proc = subprocess.Popen(args, stdin=slave, stdout=slave, stderr=slave, preexec_fn=os.setsid)
    os.close(slave)
    time.sleep(0.6)
    out=b""
    flags = fcntl.fcntl(master, fcntl.F_GETFL)
    fcntl.fcntl(master, fcntl.F_SETFL, flags | os.O_NONBLOCK)
    start=time.time()
    while time.time()-start<0.5:
        try:
            r,_,_=select.select([master],[],[],0.05)
            if r:
                d=os.read(master,8192)
                if d: out+=d
        except: break
    try:
        proc.terminate(); proc.wait(timeout=0.5)
    except:
        try: proc.kill(); proc.wait(timeout=0.5)
        except: pass
    try:
        while True:
            r,_,_=select.select([master],[],[],0.02)
            if not r: break
            d=os.read(master,8192)
            if not d: break
            out+=d
    except: pass
    os.close(master)
    # extract lesson via regex
    m = re.search(rb'\x1b\[7;\d+H\x1b\[1m([^\x1b]+)', out)
    if m:
