import subprocess, pty, os, time, fcntl, select, struct, termios, re, concurrent.futures, random

def cap(top, n_flag):
    master, slave = pty.openpty()
    try:
        fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", 24, 80, 0,0))
    except: pass
    args = ["./executable","--n", n_flag, "--top", str(top), "--combi","1","--rep","1"]
    proc = subprocess.Popen(args, stdin=slave, stdout=slave, stderr=slave, preexec_fn=os.setsid)
    os.close(slave)
    time.sleep(0.30)
    out=b""
    flags = fcntl.fcntl(master, fcntl.F_GETFL)
    fcntl.fcntl(master, fcntl.F_SETFL, flags | os.O_NONBLOCK)
    start=time.time()
    while time.time()-start<0.30:
        try:
            r,_,_=select.select([master],[],[],0.04)
            if r:
                d=os.read(master,8192)
                if d: out+=d
        except: break
    try:
        proc.terminate(); proc.wait(timeout=0.3)
    except:
        try: proc.kill(); proc.wait(timeout=0.3)
        except: pass
    try:
        while True:
            r,_,_=select.select([master],[],[],0.01)
            if not r: break
            d=os.read(master,8192)
            if not d: break
            out+=d
    except: pass
    os.close(master)
    m = re.search(rb'\x1b\[7;\d+H\x1b\[1m([^\x1b]+)', out)
    if m:
        return m.group(1).decode(errors='ignore').strip()
    return None

def find_new(prev, n_flag, top, trials=40, parallel=12):
    # attempt to find new element(s) not in prev
    pool=set()
    def task(_):
        return cap(top, n_flag)
    for _ in range(5):  # repeat batches
        with concurrent.futures.ThreadPoolExecutor(max_workers=parallel) as ex:
            futs=[ex.submit(task, i) for i in range(trials)]
            for f in concurrent.futures.as_completed(futs):
                try:
                    l=f.result()
                    if l: pool.add(l)
                except: pass
        new = pool - prev
        if new:
            return new
        time.sleep(0.1)
    return set()

n_flag="3"
prev=set()
order=[]
for top in range(1,21):
    new=find_new(prev, n_flag, top, trials=35, parallel=12)
    print(f"top {top} new {new} prev {sorted(prev)[:3]}...")
    if new:
        # if multiple new, we expected only one for increment 1, but pick one
        # For top = len(prev)+1, should be exactly one new, else multiple indicates we missed earlier
