        with concurrent.futures.ThreadPoolExecutor(max_workers=parallel) as ex:
            futs=[ex.submit(task, i) for i in range(trials)]
            for f in concurrent.futures.as_completed(futs):
                try:
                    l=f.result()
                    if l: pool.add(l)
                except: pass
        new = pool - prev
        if new:
            return new
        time.sleep(0.1)
    return set()

