fn parse_int_or_clap_error(val: &str, flag: &str, value_name: &str) -> i32 {
    match val.parse::<i32>() {
        Ok(v) => v,
        Err(_) => {
            eprintln!("error: invalid value '{}' for '--{} <{}>': invalid digit found in string\n\nFor more information, try '--help'.", val, flag, value_name);
            process::exit(2);
        }
    }
}

