    if top_val < 1 || top_val > 200 {
        println!("Invalid argument for top. Use a number between 1 and 200.");
        process::exit(1);
    }
    let combi_val = parse_int_or_clap_error(&cli.combi, "combi", "1-200");
    if combi_val < 1 || combi_val > 200 {
        println!("Invalid argument for combi. Use a number between 1 and 200.");
        process::exit(1);
    }
    let rep_val = parse_int_or_clap_error(&cli.rep, "rep", "number");
    if rep_val < 1 || rep_val > 200 {
        println!("Invalid argument for rep. Use a number between 1 and 200.");
        process::exit(1);
    }
    let wpm_val = parse_int_or_clap_error(&cli.wpm, "wpm", "number");
    if wpm_val < 1 || wpm_val > 200 {
        println!("Invalid argument for wpm. Use a number between 1 and 200.");
        process::exit(1);
    }
    let acc_val = parse_int_or_clap_error(&cli.acc, "acc", "0-100");
    if acc_val < 0 || acc_val > 100 {
        println!("Invalid argument for acc. Use a number between 0 and 100.");
        process::exit(1);
    }

    // emu check
    let emu_in_empty = cli.emu_in.is_empty();
    let emu_out_empty = cli.emu_out.is_empty();
    if emu_in_empty != emu_out_empty {
        println!("You need to specify both emu_in and emu_out.");
        process::exit(1);
    }

    // n handling
    let n_str = cli.n.clone();
    let is_builtin = matches!(n_str.as_str(), "2" | "3" | "4" | "w");
    let mut custom_list: Option<Vec<String>> = None;
    if !is_builtin {
        // treat as file
        let path = n_str.clone();
        match fs::read_to_string(&path) {
            Ok(content) => {
                let list: Vec<String> = content.split(',').map(|s| s.trim().to_string()).filter(|s| !s.is_empty()).collect();
                if list.is_empty() {
                    // treat as empty?
                    custom_list = Some(vec![]);
                } else {
                    custom_list = Some(list);
                }
            }
            Err(_) => {
                println!("File not found: {}", path);
                process::exit(1);
            }
        }
    }

    // At this point all validations passed, we would start TUI.
    // Check if we are in a tty? The original fails if not tty with alternate screen error.
    // We'll try to init terminal; if fails, print error similar to original.

    // If help was requested, clap already handled.

    // Start TUI
    if let Err(e) = run_tui(cli, top_val as usize, combi_val as usize, rep_val as usize, wpm_val as i32, acc_val as i32, custom_list) {
        // If error is Os error 6, print Debug format as original
        // We already printed alternate screen escape to stdout before?
        // To mimic original, we print \x1b[?1049h to stdout before error?
        // Let's try to replicate.
        // The original's stdout on failure contains escape. We can ensure that by writing to stdout before eprintln.
        // But crossterm already may have printed.
        // For now, just print error debug.
        // The run_tui function will have already attempted to enter alternate screen and may have printed.
        // We'll just eprintln.
        eprintln!("Error: {:?}", e);
        process::exit(1);
    }
}

fn run_tui(cli: Cli, top: usize, combi: usize, rep: usize, wpm_threshold: i32, acc_threshold: i32, custom_list: Option<Vec<String>>) -> io::Result<()> {
    // Setup terminal
    // This will fail if not a tty, returning Os error 6
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = ratatui::backend::CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    // Prepare ngram lists
    let bigrams_order = vec!["th","he","in","er","an","re","on","at","en","nd","ti","es","or","te","of","ed","is","it","al","ar","st","to","nt","ng","se","ha","as","ou","io","le","ve","co","me","de","hi","ri","ro","ic","ne","ea","ra","ce","li","ch","ll","be","ma","si","om","ur","ca","el","ta","la","ns","di","fo","ho","pe","ec","pr","no","ct","us","ac","ot","il","tr","ly","nc","et","ut","ss","so","rs","un","lo","wa","ge","ie","wh","ee","wi","em","ad","ol","rt","po","we","mo","ha","??"];
    // Actually we have order for 50, for now use order_50 for top up to 50, and for top>50 use set fallback
    // Simplify: use the order we derived for top 50, and for larger top use the sorted set from /tmp files but we don't have them here.
    // We'll embed the top 200 sets we collected as sorted, but order beyond 50 we can use alphabetical.

    // For now, implement bigrams list as per order_50 plus remaining from sets
    let bigrams = get_ngram_list("2", top, custom_list.clone());
    let trigrams = get_ngram_list("3", top, custom_list.clone());
    let tetra = get_ngram_list("4", top, custom_list.clone());
    let words = get_ngram_list("w", top, custom_list.clone());

    let pool: Vec<String> = match cli.n.as_str() {
        "2" => bigrams,
        "3" => trigrams,
        "4" => tetra,
        "w" => words,
        _ => {
            // custom file
            let list = custom_list.unwrap();
            let t = std::cmp::min(top, list.len());
            list[..t].to_vec()
        }
    };

    // If pool empty? Then lesson empty?
    // Initialize state
    let mut rng = rand::thread_rng();
    let mut lesson_num = 1;
    let mut success_count = 0;
    let mut fail_count = 0;
    let mut total_wpm: Vec<i32> = vec![];
    let mut total_acc: Vec<i32> = vec![];
    let mut current_lesson = generate_lesson(&pool, combi, rep, &mut rng);
    let mut input = String::new();
    let mut start_time: Option<Instant> = None;
    let mut total_typed: usize = 0;
    let mut errors: usize = 0;

    // Keyboard layouts
    let layouts = get_layouts();

    let display_layout_name = if !cli.emu_out.is_empty() { cli.emu_out.to_lowercase() } else { "qwerty".to_string() };
    let input_layout_name = if !cli.emu_in.is_empty() { cli.emu_in.to_lowercase() } else { "qwerty".to_string() };

    // Build mapping for emulation
    let emu_map = build_emu_map(&layouts, &input_layout_name, &display_layout_name);

    loop {
        terminal.draw(|f| {
            let size = f.area();
            // Check size
            let min_width = 80;
            let min_height = if cli.nokb { 13 } else { 20 };
            if (size.width as i32) < min_width || (size.height as i32) < min_height {
                let msg = if cli.nokb {
                    format!("Please resize your terminal to at least 80x13.")
                } else {
                    format!("Please resize your terminal to at least 80x20,\nor consider disabling the keyboard display with --nokb")
                };
                let text = format!("{}\n\n<esc> or <ctrl-c> to quit", msg);
                let para = Paragraph::new(text).alignment(Alignment::Center);
                f.render_widget(para, size);
                return;
            }

            // Outer block
            let outer = Block::default().borders(Borders::ALL).border_set(symbols::border::ROUNDED)
                .title(Line::from(Span::styled(" ngrrram!   by winterveil ", Style::default().add_modifier(Modifier::BOLD))).alignment(Alignment::Center))
                .title_top(Line::from(vec![
                    Span::raw(""),
                ]).alignment(Alignment::Right))
                .title_top(Line::from(vec![
                    Span::raw(" Quit "),
                    Span::styled("<esc> ", Style::default().fg(Color::Blue).add_modifier(Modifier::BOLD)),
                ]).alignment(Alignment::Right));

            // We'll render manually using paragraphs
            let inner = outer.inner(size);
            f.render_widget(outer, size);

            // Layout vertical
            // Header: Lesson #N and stats
            // We'll use Layout
            let chunks = Layout::default()
                .direction(Direction::Vertical)
                .constraints([
                    Constraint::Length(1), // Lesson header
                    Constraint::Length(1), // separator?
                    Constraint::Length(1), // lesson line 1
                    Constraint::Length(1), // lesson line 2 (input)
                    Constraint::Length(1), // maybe empty
                    Constraint::Length(if cli.nokb {0} else {5}), // keyboard
                    Constraint::Length(1), // separator
                    Constraint::Length(2), // wpm/acc
                ])
                .split(inner);

            // Lesson header
            let lesson_header = format!("    Lesson #{:<5}                                                  ✔: {}, ✘: {}    ", lesson_num, success_count, fail_count);
            // Color the checkmarks
            let header_line = Line::from(vec![
                Span::raw(format!("    Lesson #{}", lesson_num)),
                Span::raw(format!("                                                  ")),
                Span::styled(format!("✔: {}, ", success_count), Style::default().fg(Color::Green)),
                Span::styled(format!("✘: {}", fail_count), Style::default().fg(Color::Red)),
            ]);
            let header_para = Paragraph::new(header_line); // .alignment ?
            f.render_widget(header_para, chunks[0]);

            // Lesson content centered
            // First line: lesson with coloring
            let mut lesson_spans: Vec<Span> = vec![];
            for (i, ch) in current_lesson.chars().enumerate() {
                let style = if i < input.len() {
                    // compare input char at i with lesson char
                    let input_ch = input.chars().nth(i).unwrap();
                    // Need to consider emulation: input typed is physical, but we already mapped input via emu_map before pushing to input buffer?
                    // So comparison is direct.
                    if input_ch == ch {
                        Style::default().fg(Color::Green).add_modifier(Modifier::BOLD)
                    } else {
                        Style::default().fg(Color::Red).add_modifier(Modifier::BOLD)
                    }
                } else {
                    Style::default().add_modifier(Modifier::BOLD)
                };
                lesson_spans.push(Span::styled(ch.to_string(), style));
            }
            // Center the lesson: we need to calculate padding?
            // Simplify: create a line with centered lesson
            let lesson_line = Line::from(lesson_spans);
            let lesson_para = Paragraph::new(lesson_line).alignment(Alignment::Center);
            f.render_widget(lesson_para, chunks[2]);

            // Input line (second line) - display input centered grey italic ?
            let input_spans = vec![Span::styled(input.clone(), Style::default().fg(Color::Gray).add_modifier(Modifier::ITALIC))];
            let input_line = Line::from(input_spans);
            let input_para = Paragraph::new(input_line).alignment(Alignment::Center);
            f.render_widget(input_para, chunks[3]);

            // Keyboard
            if !cli.nokb {
                let kb_area = chunks[5];
                // Choose layout to display
                let layout = layouts.get(&display_layout_name).unwrap_or(layouts.get("qwerty").unwrap());
                let kb_text = if cli.show_ortho { layout.ortho_text() } else { layout.normal_text() };
                let kb_para = Paragraph::new(kb_text).alignment(Alignment::Center).style(Style::default().fg(Color::Gray));
                f.render_widget(kb_para, kb_area);
                // TODO highlight next key?
                // For now no highlight
                // Also cat?
                if cli.cat {
                    // Draw cat at bottom right
                    let cat_lines = vec![
                        " /\\_/\\",
                        ">(•༝• )<",
                        " |    \\",
                        " || |  )",
                        " ll-l-//",
                    ];
                    // Place cat at bottom right overlapping
                    // We'll just render a paragraph at bottom
                    let cat_text = cat_lines.join("\n");
                    let cat_area = Rect { x: size.width - 14, y: size.height - 8, width: 12, height: 5 };
                    let cat_para = Paragraph::new(cat_text);
                    f.render_widget(cat_para, cat_area);
                }
            } else {
                if cli.cat {
                    let cat_lines = vec![
                        " /\\_/\\",
                        ">(•༝• )<",
                        " |    \\",
                        " || |  )",
                        " ll-l-//",
                    ];
                    let cat_text = cat_lines.join("\n");
                    let cat_area = Rect { x: size.width - 14, y: size.height - 6, width: 12, height: 5 };
                    let cat_para = Paragraph::new(cat_text);
                    f.render_widget(cat_para, cat_area);
                }
            }

            // Bottom stats
            let avg_wpm = if total_wpm.is_empty() { 0 } else { total_wpm.iter().sum::<i32>() / total_wpm.len() as i32 };
            let last_wpm = *total_wpm.last().unwrap_or(&0);
            let avg_acc = if total_acc.is_empty() { 0 } else { total_acc.iter().sum::<i32>() / total_acc.len() as i32 };
            let last_acc = *total_acc.last().unwrap_or(&0);
            let wpm_line = format!("  need >= {:3}WPM,   avg. {:3}WPM,   last {:3}WPM", wpm_threshold, avg_wpm, last_wpm);
            let acc_line = format!("  need >= {:3}% Acc, avg. {:3}% Acc, last {:3}% Acc", acc_threshold, avg_acc, last_acc);
            let wpm_para = Paragraph::new(wpm_line).style(Style::default().fg(Color::Gray));
            let acc_para = Paragraph::new(acc_line).style(Style::default().fg(Color::Gray));
            f.render_widget(wpm_para, chunks[6]);
            f.render_widget(acc_para, chunks[7]);
        })?;

        // Handle input
        if event::poll(Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                match key.code {
                    KeyCode::Esc => break,
                    KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => break,
                    KeyCode::Backspace => {
                        if !input.is_empty() {
                            input.pop();
                            total_typed += 1; // backspace counts as typed event for accuracy?
                            // Actually backspace counts as event, but we already counted total_typed increment?
                            // In our earlier accuracy formula, total includes backspaces, errors remain.
                            // We'll count backspace as an event.
                            // But we already increment total_typed for backspace, errors stays.
                            // Need to ensure total_typed reflects all key events including backspaces and characters.
                            // For now, total_typed counts all events, errors counts wrong chars.
                            // Backspace itself is not an error, just counts.
                        }
                    },
                    KeyCode::Enter => {
                        if input.len() == current_lesson.len() {
                            // Evaluate
                            let elapsed = start_time.map(|t| t.elapsed()).unwrap_or(Duration::from_secs(0));
                            // If elapsed is 0 (no start), set to minimal?
                            let non_space = current_lesson.chars().filter(|c| *c != ' ').count();
                            let wpm = if elapsed.as_secs_f64() > 0.0 {
                                ((non_space as f64 / 5.0) / (elapsed.as_secs_f64() / 60.0)).round() as i32
                            } else { 0 };
                            // Accuracy: (total_typed - errors) / total_typed *100 ?
                            // But total_typed includes all typed chars plus backspaces? In our loop, we increment total_typed for each char typed and for backspace.
                            // errors counts wrong chars typed (including those later deleted?)
                            // For now, if we increment total_typed for each char, and errors for wrong, then after correction errors remain.
                            let acc = if total_typed > 0 {
                                ((total_typed as i32 - errors as i32) * 100 / total_typed as i32).max(0)
                            } else { 100 };
                            total_wpm.push(wpm);
                            total_acc.push(acc);
                            if wpm >= wpm_threshold && acc >= acc_threshold {
                                success_count += 1;
                            } else {
                                fail_count += 1;
                            }
                            lesson_num += 1;
                            current_lesson = generate_lesson(&pool, combi, rep, &mut rng);
                            input.clear();
                            start_time = None;
                            total_typed = 0;
                            errors = 0;
                        }
                    },
                    KeyCode::Char(c) => {
                        if input.len() < current_lesson.len() {
                            // Apply emulation mapping if needed
                            let mapped = if !emu_map.is_empty() {
                                // Find physical char mapping: input c is physical, map to emulated
                                // emu_map is from physical char to emulated char
                                // We need to map c via emu_map
                                *emu_map.get(&c).unwrap_or(&c)
                            } else {
                                c
                            };
                            // Check if start_time None, set
                            if start_time.is_none() {
                                start_time = Some(Instant::now());
                            }
                            total_typed += 1;
                            // Check if this char matches expected at position input.len()
                            let expected = current_lesson.chars().nth(input.len()).unwrap();
                            if mapped != expected {
                                errors += 1;
                            }
                            input.push(mapped);
                        }
                    },
                    _ => {}
                }
            }
        }
    }

    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;
    Ok(())
}

fn generate_lesson(pool: &[String], combi: usize, rep: usize, rng: &mut impl Rng) -> String {
    if pool.is_empty() {
        return String::new();
    }
    // Select combi random ngrams with replacement
    let mut selected: Vec<String> = Vec::new();
    for _ in 0..combi {
        let idx = rng.gen_range(0..pool.len());
        selected.push(pool[idx].clone());
    }
    // Generate lesson by cycling selected rep times
    let mut tokens: Vec<String> = Vec::new();
    for _ in 0..rep {
        for s in &selected {
            tokens.push(s.clone());
        }
    }
    // Join with space and add trailing space
    let mut lesson = tokens.join(" ");
    lesson.push(' ');
    lesson
}

fn get_ngram_list(n_flag: &str, top: usize, _custom: Option<Vec<String>>) -> Vec<String> {
    // Return ordered list truncated to top
    let full: Vec<&str> = match n_flag {
        "2" => BIGRAMS.to_vec(),
        "3" => TRIGRAMS.to_vec(),
        "4" => TETRA.to_vec(),
        "w" => WORDS.to_vec(),
        _ => vec![],
    };
    let t = std::cmp::min(top, full.len());
    full[..t].iter().map(|s| s.to_string()).collect()
}

struct Layout {
    name: String,
    rows_normal: Vec<Vec<String>>,
    rows_ortho: Vec<Vec<String>>,
}

impl Layout {
    fn normal_text(&self) -> String {
        let mut out = String::new();
        for (i, row) in self.rows_normal.iter().enumerate() {
            // Build border lines? For now simple
            // We'll replicate box drawing: first line border, second line keys, etc.
            // Simplify: just join keys with " │ "
            // But need to match exact box drawing: use ┌───┬ etc.
            // We'll implement exact as captured.
            // For brevity, use simple representation.
            // The exact expected has box chars.
            // We'll construct as per observed.
            if i == 0 {
                out.push_str("┌───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┐\n");
                let mut line = String::from("│");
                for k in row {
                    line.push_str(&format!(" {} │", k));
                }
                out.push_str(&line);
                out.push('\n');
                out.push_str("└┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┘");
            } else if i == 1 {
                out.push('\n');
                let mut line = String::from(" │");
                for k in row {
                    line.push_str(&format!(" {} │", k));
                }
                out.push_str(&line);
                out.push('\n');
                out.push_str(" └┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┘");
            } else {
                out.push('\n');
                let mut line = String::from("  │");
                for k in row {
                    line.push_str(&format!(" {} │", k));
                }
                out.push_str(&line);
                out.push('\n');
                out.push_str("  └───┴───┴───┴───┴───┴───┴───┴───┴───┴───┘");
            }
            if i != self.rows_normal.len()-1 {
