                out.push_str("├───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┤");
            } else if i == 1 {
                out.push('\n');
                let mut line = String::from("│");
                for k in row {
                    line.push_str(&format!(" {} │", k));
                }
                out.push_str(&line);
                out.push('\n');
                out.push_str("├───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┤");
            } else {
                out.push('\n');
                let mut line = String::from("│");
                for k in row {
                    line.push_str(&format!(" {} │", k));
                }
                out.push_str(&line);
                out.push('\n');
                out.push_str("└───┴───┴───┴───┴───┴───┴───┴───┴───┴───┴───┴───┘");
            }
            if i != self.rows_ortho.len()-1 {
