                    "Please resize your terminal to at least 80x13."
                } else {
                    "Please resize your terminal to at least 80x20,\nor consider disabling the keyboard display with --nokb"
                };
                let text = format!("{}\n\n<esc> or <ctrl-c> to quit", msg);
                let para = Paragraph::new(text).alignment(Alignment::Center);
                f.render_widget(para, size);
                return;
            }

            let outer = Block::default().borders(Borders::ALL).border_set(symbols::border::ROUNDED)
                .title(Line::from(Span::styled(" ngrrram!   by winterveil ", Style::default().add_modifier(Modifier::BOLD))).alignment(Alignment::Center));

            // We'll handle Quit title manually via overlay: just draw outer and then draw Quit at top right
            // But we can also set title_top
            // Instead use block with title_top
            let outer_with_title = Block::default().borders(Borders::ALL).border_set(symbols::border::ROUNDED)
                .title(Line::from(Span::styled(" ngrrram!   by winterveil ", Style::default().add_modifier(Modifier::BOLD))).alignment(Alignment::Center))
                .title_top(Line::from(vec![
                    Span::raw(" Quit "),
                    Span::styled("<esc> ", Style::default().fg(Color::Blue).add_modifier(Modifier::BOLD)),
                ]).alignment(Alignment::Right));

            let inner = outer_with_title.inner(size);
            f.render_widget(outer_with_title, size);

            // Layout vertical
            let chunks = ratatui::layout::Layout::default()
                .direction(Direction::Vertical)
                .constraints([
                    Constraint::Length(1), // Lesson header line
                    Constraint::Length(1), // separator
                    Constraint::Length(1), // empty?
                    Constraint::Length(1), // lesson line
                    Constraint::Length(1), // input line
                    Constraint::Length(if nokb_c {0} else {5}), // keyboard area
                    Constraint::Length(1), // separator?
                    Constraint::Length(2), // stats
                ])
                .split(inner);

            // Actually need to adjust indices: let's map observed layout
            // Original has:
            // Row: 0: header "Lesson #..."
            // 1: separator line
            // 2: blank
            // 3: lesson centered
            // 4: input centered (or blank)
            // 5: keyboard (5 lines)
            // Then separator and stats
            // For simplicity, we place header at chunks[0], lesson at chunks[3], input at chunks[4], keyboard at chunks[5], stats at chunks[7]

            let header_line = Line::from(vec![
                Span::raw(format!("    Lesson #{}                                                  ", lesson_num_c)),
                Span::styled(format!("✔: {}, ", cur_success), Style::default().fg(Color::Green)),
                Span::styled(format!("✘: {}", cur_fail), Style::default().fg(Color::Red)),
            ]);
            f.render_widget(Paragraph::new(header_line), chunks[0]);
            // separator line: we'll just render a line of "─"
            let sep = "─".repeat(inner.width as usize);
            f.render_widget(Paragraph::new(sep.clone()), chunks[1]);
            // lesson line
            let mut lesson_spans: Vec<Span> = vec![];
            for (i, ch) in cur_lesson.chars().enumerate() {
                let style = if i < cur_input.len() {
                    let ic = cur_input.chars().nth(i).unwrap();
                    if ic == ch {
                        Style::default().fg(Color::Green).add_modifier(Modifier::BOLD)
                    } else {
                        Style::default().fg(Color::Red).add_modifier(Modifier::BOLD)
                    }
                } else {
                    Style::default().add_modifier(Modifier::BOLD)
                };
                lesson_spans.push(Span::styled(ch.to_string(), style));
            }
            let lesson_line = Line::from(lesson_spans);
            f.render_widget(Paragraph::new(lesson_line).alignment(Alignment::Center), chunks[3]);
            let input_line = Line::from(vec![Span::styled(cur_input.clone(), Style::default().fg(Color::Gray).add_modifier(Modifier::ITALIC))]);
            f.render_widget(Paragraph::new(input_line).alignment(Alignment::Center), chunks[4]);

            if !nokb_c {
                let kb_area = chunks[5];
                if let Some(layout) = layouts_ref.get(&disp_name) {
                    let kb_text = if show_o { layout.ortho_text() } else { layout.normal_text() };
                    let kb_para = Paragraph::new(kb_text).alignment(Alignment::Center).style(Style::default().fg(Color::Gray));
                    f.render_widget(kb_para, kb_area);
                }
                if cat_c {
                    // Simple cat drawn at bottom right
                    // We'll draw over the outer border area? Use size
                    // Place cat at bottom
                }
            } else {
                if cat_c {
                    // cat still?
                }
            }
            // separator before stats
            f.render_widget(Paragraph::new(sep.clone()), chunks[6]);
            let avg_wpm = if cur_total_wpm.is_empty() { 0 } else { cur_total_wpm.iter().sum::<i32>() / cur_total_wpm.len() as i32 };
            let last_wpm = *cur_total_wpm.last().unwrap_or(&0);
            let avg_acc = if cur_total_acc.is_empty() { 0 } else { cur_total_acc.iter().sum::<i32>() / cur_total_acc.len() as i32 };
            let last_acc = *cur_total_acc.last().unwrap_or(&0);
            let wpm_line = format!("  need >= {:3}WPM,   avg. {:3}WPM,   last {:3}WPM", wpm_thr, avg_wpm, last_wpm);
            let acc_line = format!("  need >= {:3}% Acc, avg. {:3}% Acc, last {:3}% Acc", acc_thr, avg_acc, last_acc);
            // Combine two lines into one chunk? We'll place both in chunks[7] with two lines
            let stats_text = format!("{}\n{}", wpm_line, acc_line);
            f.render_widget(Paragraph::new(stats_text).style(Style::default().fg(Color::Gray)), chunks[7]);

            // If cat, draw cat text at overlapping area: we'll just draw a paragraph at bottom right using size
            if cat_c {
                let cat_str = if nokb_c {
                    " /\\_/\\\n>(•༝• )<\n |    \\\n || |  )\n ll-l-//"
                } else {
                    "  /\\_/\\\n >(•༝• )<\n  |    \\\n  || |  )\n  ll-l-//"
                };
                // We'll render cat at absolute position near bottom right
                // Use size minus offset
                // For now, skip precise positioning and just rely on previous keyboard area? The earlier capture shows cat at right side near keyboard bottom.
                // We'll create a paragraph with cat and render at a rect
                let cat_area = Rect { x: size.width.saturating_sub(14), y: size.height.saturating_sub(8), width: 12, height: 5 };
                f.render_widget(Paragraph::new(cat_str), cat_area);
            }
        })?;

        if event::poll(Duration::from_millis(100))? {
            if let Event::Key(key) = event::read()? {
                match key.code {
                    KeyCode::Esc => break,
                    KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => break,
                    KeyCode::Backspace => {
                        if !input.is_empty() {
                            input.pop();
                            total_typed += 1;
                        }
                    }
                    KeyCode::Enter => {
                        if input.len() == current_lesson.len() {
                            let elapsed = start_time.map(|t| t.elapsed()).unwrap_or(Duration::from_secs(0));
                            let non_space = current_lesson.chars().filter(|c| *c != ' ').count();
                            let wpm = if elapsed.as_secs_f64() > 0.0 {
                                ((non_space as f64 / 5.0) / (elapsed.as_secs_f64() / 60.0)).round() as i32
                            } else { 0 };
                            let acc = if total_typed > 0 {
                                ((total_typed as i32 - errors as i32) * 100 / total_typed as i32).max(0)
                            } else { 100 };
                            total_wpm.push(wpm);
                            total_acc.push(acc);
                            if wpm >= wpm_threshold && acc >= acc_threshold {
                                success_count += 1;
                            } else {
                                fail_count += 1;
                            }
                            lesson_num += 1;
                            current_lesson = generate_lesson(&pool, combi, rep, &mut rng);
                            input.clear();
                            start_time = None;
                            total_typed = 0;
                            errors = 0;
                        }
                    }
                    KeyCode::Char(c) => {
                        if input.len() < current_lesson.len() {
                            let mapped = if !emu_map.is_empty() {
                                *emu_map.get(&c).unwrap_or(&c)
                            } else {
                                c
                            };
                            // Also need to consider uppercase? For now handle as is
                            if start_time.is_none() {
                                start_time = Some(Instant::now());
                            }
                            total_typed += 1;
                            let expected = current_lesson.chars().nth(input.len()).unwrap();
                            if mapped != expected {
                                errors += 1;
                            }
                            input.push(mapped);
                            // Also need to handle space? Space is included in lesson, so typing space is required.
                        }
                    }
                    _ => {}
                }
            }
        }
    }

    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;
    Ok(())
}

fn generate_lesson(pool: &[String], combi: usize, rep: usize, rng: &mut impl Rng) -> String {
    if pool.is_empty() {
        return String::new();
    }
    let mut selected: Vec<String> = Vec::new();
    for _ in 0..combi {
        let idx = rng.gen_range(0..pool.len());
        selected.push(pool[idx].clone());
    }
    let mut tokens: Vec<String> = Vec::new();
    for _ in 0..rep {
        for s in &selected {
            tokens.push(s.clone());
        }
    }
    let mut lesson = tokens.join(" ");
    lesson.push(' ');
    lesson
}

fn get_ngram_list(n_flag: &str, top: usize, _custom: Option<Vec<String>>) -> Vec<String> {
    let full: Vec<&str> = match n_flag {
        "2" => BIGRAMS.to_vec(),
        "3" => TRIGRAMS.to_vec(),
        "4" => TETRA.to_vec(),
        "w" => WORDS.to_vec(),
        _ => vec![],
    };
    let t = std::cmp::min(top, full.len());
    full[..t].iter().map(|s| s.to_string()).collect()
}

struct KeyboardLayout {
    name: String,
    rows_normal: Vec<Vec<String>>,
    rows_ortho: Vec<Vec<String>>,
}

impl KeyboardLayout {
    fn normal_text(&self) -> String {
        let mut out = String::new();
        for (i, row) in self.rows_normal.iter().enumerate() {
            if i == 0 {
                out.push_str("┌───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┐\n");
                let mut line = String::from("│");
                for k in row {
                    line.push_str(&format!(" {} │", k));
                }
                out.push_str(&line);
                out.push_str("\n└┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┘");
            } else if i == 1 {
                out.push_str("\n │");
                for k in row {
                    out.push_str(&format!(" {} │", k));
                }
                out.push_str("\n └┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┘");
            } else {
                out.push_str("\n  │");
                for k in row {
                    out.push_str(&format!(" {} │", k));
                }
                out.push_str("\n  └───┴───┴───┴───┴───┴───┴───┴───┴───┴───┘");
            }
        }
        out
    }
    fn ortho_text(&self) -> String {
        let mut out = String::new();
        for (i, row) in self.rows_ortho.iter().enumerate() {
            if i == 0 {
                out.push_str("┌───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┐\n");
                let mut line = String::from("│");
                for k in row {
                    line.push_str(&format!(" {} │", k));
                }
                out.push_str(&line);
                out.push_str("\n├───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┤");
            } else if i == 1 {
                out.push_str("\n│");
                for k in row {
                    out.push_str(&format!(" {} │", k));
                }
                out.push_str("\n├───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┤");
            } else {
                out.push_str("\n│");
                for k in row {
                    out.push_str(&format!(" {} │", k));
                }
                out.push_str("\n└───┴───┴───┴───┴───┴───┴───┴───┴───┴───┴───┴───┘");
            }
        }
        out
    }
}

