fn build_emu_map(layouts: &std::collections::HashMap<String, KeyboardLayout>, input: &str, output: &str) -> std::collections::HashMap<char, char> {
    let mut map = std::collections::HashMap::new();
    if input == output || input.is_empty() || output.is_empty() {
        return map;
    }
    let in_layout = layouts.get(input).or_else(|| layouts.get("qwerty")).unwrap();
    let out_layout = layouts.get(output).or_else(|| layouts.get("qwerty")).unwrap();
    for r in 0..in_layout.rows_normal.len() {
        let in_row = &in_layout.rows_normal[r];
        let out_row = &out_layout.rows_normal[r];
        for c in 0..std::cmp::min(in_row.len(), out_row.len()) {
            let in_ch = in_row[c].chars().next().unwrap_or(' ');
            let out_ch = out_row[c].chars().next().unwrap_or(' ');
            map.insert(in_ch, out_ch);
            map.insert(in_ch.to_ascii_uppercase(), out_ch.to_ascii_uppercase());
        }
    }
    map.insert(' ', ' ');
    map
}

