    let mut terminal = Terminal::new(backend)?;

    let bigrams = get_ngram_list("2", top, custom_list.clone());
    let trigrams = get_ngram_list("3", top, custom_list.clone());
    let tetra = get_ngram_list("4", top, custom_list.clone());
    let words = get_ngram_list("w", top, custom_list.clone());

