    if combi_val < 1 || combi_val > 200 { println!("Invalid argument for combi. Use a number between 1 and 200."); process::exit(1); }
    let rep_val = parse_int_or_clap_error(&rep_str, "rep", "number");
    if rep_val < 1 || rep_val > 200 { println!("Invalid argument for rep. Use a number between 1 and 200."); process::exit(1); }
    let wpm_val = parse_int_or_clap_error(&wpm_str, "wpm", "number");
    if wpm_val < 1 || wpm_val > 200 { println!("Invalid argument for wpm. Use a number between 1 and 200."); process::exit(1); }
    let acc_val = parse_int_or_clap_error(&acc_str, "acc", "0-100");
    if acc_val < 0 || acc_val > 100 { println!("Invalid argument for acc. Use a number between 0 and 100."); process::exit(1); }

    if (emu_in.is_empty() != emu_out.is_empty()) { println!("You need to specify both emu_in and emu_out."); process::exit(1); }

    let is_builtin = matches!(n.as_str(), "2" | "3" | "4" | "w");
    let mut custom_list: Option<Vec<String>> = None;
    if !is_builtin {
        let path = n.clone();
        match fs::read_to_string(&path) {
            Ok(content) => {
                let list: Vec<String> = content.split(',').map(|s| s.trim().to_string()).filter(|s| !s.is_empty()).collect();
                custom_list = Some(list);
            }
            Err(_) => { println!("File not found: {}", path); process::exit(1); }
        }
    }

    if let Err(e) = run_tui(n, top_val as usize, combi_val as usize, rep_val as usize, wpm_val as i32, acc_val as i32, show_ortho, nokb, cat, emu_in, emu_out, custom_list) {
        eprintln!("Error: {:?}", e);
        process::exit(1);
    }
}
