                        if input.len() == current_lesson.len() {
                            let elapsed = start_time.map(|t| t.elapsed()).unwrap_or(Duration::from_secs(0));
                            let non_space = current_lesson.chars().filter(|c| *c != ' ').count();
                            let wpm = if elapsed.as_secs_f64() > 0.0 {
                                ((non_space as f64 / 5.0) / (elapsed.as_secs_f64() / 60.0)).round() as i32
                            } else { 0 };
                            let acc = if total_typed > 0 { ((total_typed as i32 - errors as i32) * 100 / total_typed as i32).max(0) } else { 100 };
                            total_wpm.push(wpm);
                            total_acc.push(acc);
                            if wpm >= wpm_threshold && acc >= acc_threshold { success_count += 1; } else { fail_count += 1; }
                            lesson_num += 1;
                            current_lesson = generate_lesson(&pool, combi, rep, &mut rng);
                            input.clear();
                            start_time = None;
                            total_typed = 0;
                            errors = 0;
                        }
                    }
                    KeyCode::Char(c) => {
                        if input.len() < current_lesson.len() {
                            let mapped = if !emu_map.is_empty() { *emu_map.get(&c).unwrap_or(&c) } else { c };
                            if start_time.is_none() { start_time = Some(Instant::now()); }
                            total_typed += 1;
                            let expected = current_lesson.chars().nth(input.len()).unwrap();
                            if mapped != expected { errors += 1; }
                            input.push(mapped);
                        }
                    }
                    _ => {}
                }
            }
        }
    }

    disable_raw_mode()?;
    execute!(stdout, LeaveAlternateScreen)?;
    Ok(())
}

fn generate_lesson(pool: &[String], combi: usize, rep: usize, rng: &mut impl Rng) -> String {
    if pool.is_empty() { return String::new(); }
    let mut selected: Vec<String> = Vec::new();
    for _ in 0..combi {
        let idx = rng.gen_range(0..pool.len());
        selected.push(pool[idx].clone());
    }
    let mut tokens: Vec<String> = Vec::new();
    for _ in 0..rep {
        for s in &selected {
            tokens.push(s.clone());
        }
    }
    let mut lesson = tokens.join(" ");
    lesson.push(' ');
    lesson
}

fn get_ngram_list(n_flag: &str, top: usize, _custom: Option<Vec<String>>) -> Vec<String> {
    let full: Vec<&str> = match n_flag {
        "2" => BIGRAMS.to_vec(),
        "3" => TRIGRAMS.to_vec(),
        "4" => TETRA.to_vec(),
        "w" => WORDS.to_vec(),
        _ => vec![],
    };
    let t = std::cmp::min(top, full.len());
    full[..t].iter().map(|s| s.to_string()).collect()
}

struct KeyboardLayout {
    name: String,
    rows_normal: Vec<Vec<String>>,
    rows_ortho: Vec<Vec<String>>,
}

impl KeyboardLayout {
    fn normal_text(&self) -> String {
        let mut out = String::new();
        for (i, row) in self.rows_normal.iter().enumerate() {
            if i == 0 {
                out.push_str("┌───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┐");
                out.push_str("\n");
                let mut line = String::from("│");
                for k in row { line.push_str(&format!(" {} │", k)); }
                out.push_str(&line);
                out.push_str("\n└┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┘");
            } else if i == 1 {
                out.push_str("\n │");
                for k in row { line: String = format!(" {} │", k); out.push_str(&line); }
                out.push_str("\n └┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┴┬──┘");
            } else {
                out.push_str("\n  │");
                for k in row { out.push_str(&format!(" {} │", k)); }
                out.push_str("\n  └───┴───┴───┴───┴───┴───┴───┴───┴───┴───┘");
            }
        }
        out
    }
    fn ortho_text(&self) -> String {
        let mut out = String::new();
        for (i, row) in self.rows_ortho.iter().enumerate() {
            if i == 0 {
                out.push_str("┌───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┐");
                out.push_str("\n");
                let mut line = String::from("│");
                for k in row { line.push_str(&format!(" {} │", k)); }
                out.push_str(&line);
                out.push_str("\n├───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┤");
            } else if i == 1 {
                out.push_str("\n│");
                for k in row { line: String = format!(" {} │", k); out.push_str(&line); }
                out.push_str("\n├───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┤");
            } else {
                out.push_str("\n│");
                for k in row { out.push_str(&format!(" {} │", k)); }
                out.push_str("\n└───┴───┴───┴───┴───┴───┴───┴───┴───┴───┴───┴───┘");
            }
        }
        out
    }
}

