cat <<'PY' > /tmp/check_cat.py
import subprocess, time, os, shlex

def cap(args, w=80,h=24):
    sess=f"c{int(time.time()*1000)%100000}"
    import random
    sess+=str(random.randint(0,9999))
    subprocess.run(["tmux","kill-session","-t",sess], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    cmd=" ".join(shlex.quote(c) for c in args)
    subprocess.run(["tmux","new-session","-d","-s",sess,"-x",str(w),"-y",str(h), cmd], check=True)
    time.sleep(0.85)
    txt=subprocess.run(["tmux","capture-pane","-p","-t",sess], capture_output=True, text=True).stdout
    subprocess.run(["tmux","kill-session","-t",sess], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    return txt

txt=cap(["./executable","--cat"])
for line in txt.splitlines():
    if "/\\_/\\" in line:
        print(repr(line))
# Check with nokb
txt=cap(["./executable","--nokb","--cat"])
for line in txt.splitlines():
    if "/\\_/\\" in line:
        print(repr(line))

# Check ortho
txt=cap(["./executable","--show-ortho"])
for line in txt.splitlines():
    if "△" in line:
        print(repr(line))

# Check top1
txt=cap(["./executable","--top","1","--combi","1","--rep","1","--n","2"])
for line in txt.splitlines():
    if "Lesson" in line:
        print(line)
for i,l in enumerate(txt.splitlines()):
    if "Lesson" in l and i+3 < len(txt.splitlines()):
